// Welzl 3D minimum enclosing ball; see package README and MIT notice.
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
struct SebPoint{double x,y,z;};struct SebSphere{SebPoint c;double r;};
static SebPoint sub3(SebPoint a,SebPoint b){return {a.x-b.x,a.y-b.y,a.z-b.z};}static SebPoint add3(SebPoint a,SebPoint b){return {a.x+b.x,a.y+b.y,a.z+b.z};}static SebPoint mul3(SebPoint a,double s){return {a.x*s,a.y*s,a.z*s};}static double dot3(SebPoint a,SebPoint b){return a.x*b.x+a.y*b.y+a.z*b.z;}static SebPoint cross3(SebPoint a,SebPoint b){return {a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}static double det3(SebPoint a,SebPoint b,SebPoint c){return dot3(a,cross3(b,c));}static SebSphere invalid3(){return {{0,0,0},-1};}
static SebSphere through3(const SebPoint*p,int n){if(n==1)return {p[0],0};if(n==2){auto c=mul3(add3(p[0],p[1]),.5);return {c,std::sqrt(dot3(sub3(p[0],c),sub3(p[0],c)))};}if(n==3){auto u=sub3(p[1],p[0]),v=sub3(p[2],p[0]),w=cross3(u,v);double d=2*dot3(w,w);if(d<1e-24)return invalid3();auto off=mul3(add3(mul3(cross3(v,w),dot3(u,u)),mul3(cross3(w,u),dot3(v,v))),1/d);auto c=add3(p[0],off);return {c,std::sqrt(dot3(sub3(c,p[0]),sub3(c,p[0])))};}auto a=mul3(sub3(p[1],p[0]),2),b=mul3(sub3(p[2],p[0]),2),c=mul3(sub3(p[3],p[0]),2);double qa=dot3(p[1],p[1])-dot3(p[0],p[0]),qb=dot3(p[2],p[2])-dot3(p[0],p[0]),qc=dot3(p[3],p[3])-dot3(p[0],p[0]),d=det3(a,b,c);if(std::abs(d)<1e-18)return invalid3();auto center=mul3(add3(add3(mul3(cross3(b,c),qa),mul3(cross3(c,a),qb)),mul3(cross3(a,b),qc)),1/d);return {center,std::sqrt(dot3(sub3(center,p[0]),sub3(center,p[0])))};}
static bool contains3(SebSphere s,SebPoint p){if(s.r<0)return false;auto d=sub3(p,s.c);return dot3(d,d)<=(s.r+1e-10)*(s.r+1e-10);}
static SebSphere fit3(const SebPoint*r,int m){auto best=invalid3();for(int mask=1;mask<(1<<m);mask++){SebPoint q[4];int n=0;for(int i=0;i<m;i++)if(mask&(1<<i))q[n++]=r[i];auto s=through3(q,n);if(s.r<0)continue;bool ok=true;for(int i=0;i<m;i++)if(!contains3(s,r[i]))ok=false;if(ok&&(best.r<0||s.r<best.r-1e-12))best=s;}return best;}
static SebSphere welzl3(const SebPoint*p,int n,SebPoint*r,int m){if(n==0||m==4)return fit3(r,m);auto s=welzl3(p,n-1,r,m);if(contains3(s,p[n-1]))return s;r[m]=p[n-1];return welzl3(p,n-1,r,m+1);}
extern "C" std::int64_t smallest_enclosing_ball_3d(const double*in,std::size_t len,double*out,std::size_t cap){if(!in||len<4||len>25||!std::isfinite(in[0])||in[0]<1||in[0]>8||in[0]!=std::floor(in[0]))return -1;int n=int(in[0]);if(len!=std::size_t(1+3*n))return -1;SebPoint p[8];for(int i=0;i<n;i++){p[i]={in[1+3*i],in[2+3*i],in[3+3*i]};if(!std::isfinite(p[i].x)||!std::isfinite(p[i].y)||!std::isfinite(p[i].z)||std::abs(p[i].x)>10||std::abs(p[i].y)>10||std::abs(p[i].z)>10)return -1;}std::sort(p,p+n,[](SebPoint a,SebPoint b){if(a.x!=b.x)return a.x<b.x;if(a.y!=b.y)return a.y<b.y;return a.z<b.z;});SebPoint r[4];auto s=welzl3(p,n,r,0);if(s.r<0||!std::isfinite(s.r))return -1;if(!out||cap<4)return -2;out[0]=s.c.x;out[1]=s.c.y;out[2]=s.c.z;out[3]=s.r;return 4;}
